-- Day Out tracker: schema, tables and row level security.
-- Run this in the Supabase SQL editor, then add "daysout" to
-- Project Settings > API > Exposed schemas so PostgREST can see it.

create schema if not exists daysout;

create table if not exists daysout.properties (
  id bigint generated by default as identity primary key,
  name text not null unique,
  location text,
  country text not null default 'England'
    check (country in ('England', 'Scotland', 'Wales', 'Northern Ireland')),
  institutions text[] not null default '{}',
  latitude double precision check (latitude between -90 and 90),
  longitude double precision check (longitude between -180 and 180),
  website text,
  notes text,
  created_at timestamptz not null default now()
);

-- A visit is a separate row rather than a flag on the property so a place can be
-- visited more than once, and so "visited but I can't remember when" stays valid
-- (visited_on is nullable).
create table if not exists daysout.visits (
  id bigint generated by default as identity primary key,
  property_id bigint not null references daysout.properties (id) on delete cascade,
  visited_on date,
  notes text,
  created_at timestamptz not null default now()
);

create index if not exists visits_property_id_idx on daysout.visits (property_id);
create index if not exists properties_institutions_idx on daysout.properties using gin (institutions);

grant usage on schema daysout to anon, authenticated;
grant all on all tables in schema daysout to anon, authenticated;
grant all on all sequences in schema daysout to anon, authenticated;

alter table daysout.properties enable row level security;
alter table daysout.visits enable row level security;

-- Signed-in users share one household list; the anon key alone cannot read or
-- write, so the published GitHub Pages build is not an open door to the data.
drop policy if exists "authenticated full access to properties" on daysout.properties;
create policy "authenticated full access to properties" on daysout.properties
for all to authenticated
using (true)
with check (true);

drop policy if exists "authenticated full access to visits" on daysout.visits;
create policy "authenticated full access to visits" on daysout.visits
for all to authenticated
using (true)
with check (true);

-- Starter list of UK properties and gardens (261 places).
-- Coordinates are approximate map positions, good to a few hundred metres, and
-- can be corrected in the app. Re-running this is safe: existing names are kept.

on conflict (name) do nothing;

-- More Historic Houses and RHS Partner Garden properties (52 places),
-- filling out two categories that were thin in the original seed. Gathered
-- from web search result snippets against historichouses.org and rhs.org.uk
-- (both block direct fetches), cross-checked against each other; coordinates
-- are approximate map positions, same as the original seed. Re-running this
-- is safe: existing names are kept, and the two institution updates below are
-- idempotent.

on conflict (name) do nothing;

-- The Eden Project and Walmer Castle both joined the RHS Partner Garden
-- scheme for 2026, after the original seed was written.
update daysout.properties
set institutions = array_append(institutions, 'RHS Partner Garden')
where name = 'The Eden Project' and not ('RHS Partner Garden' = any(institutions));

update daysout.properties
set institutions = array_append(institutions, 'RHS Partner Garden')
where name = 'Walmer Castle and Gardens' and not ('RHS Partner Garden' = any(institutions));

-- More Historic Houses properties (37 places), reported missing by name
-- (Doddington House, Godinton House) and followed up with a broader regional
-- sweep (Kent, Sussex, Yorkshire, Cotswolds/Midlands, North West, East
-- Anglia, Cornwall/Devon, Scotland, Wales) cross-checked against the existing
-- seed. Gathered from web search result snippets against historichouses.org
-- (which blocks direct fetches), not scraped from an official directory;
-- coordinates are approximate map positions, same caveat as the rest of the
-- seed. Re-running this is safe: existing names are kept.
--
-- No "Doddington House" member could be found under that exact name or in
-- Wiltshire as reported — likely a mix-up with one of these two similarly
-- named members, both included so either (or both) can stay:
-- Doddington Hall and Gardens (Lincolnshire) and Doddington Place Gardens
-- (Kent).

on conflict (name) do nothing;

-- More English Heritage properties (55 places), following up on a report
-- that Hurst Castle was missing, with a broader sweep across London, Kent,
-- Sussex, Hampshire/Isle of Wight, Yorkshire, Northumberland, Cumbria,
-- Cornwall/Devon, East Anglia/Essex, the Midlands, Herefordshire, Somerset
-- and Wiltshire, cross-checked against the existing seed to avoid
-- duplicates. Gathered from web search result snippets against
-- english-heritage.org.uk (which blocks direct fetches) and Wikipedia, not
-- scraped from an official directory; coordinates are approximate map
-- positions, same caveat as the rest of the seed. Re-running this is safe:
-- existing names are kept.
--
-- Three are worth a second look rather than being treated as certain:
-- Conisbrough Castle is jointly associated with Doncaster council rather
-- than solely English Heritage; Leiston Abbey was reported as closed to
-- visitors pending conservation work; Bayham Old Abbey's coordinates came
-- from a lower-confidence source than the others here. All three are kept
-- in since the institution tag and coordinates are already treated as
-- correctable starting points throughout this seed.

on conflict (name) do nothing;

-- 97 historic parish churches and cathedrals across Kent, East Sussex and
-- West Sussex, sourced from the user's own standalone reference app (not
-- scraped or web-searched, unlike earlier seed batches). New "Historic
-- Church" institution/group, its own progress card and map colour, distinct
-- from the four existing groups. The source data has five metadata fields
-- (built, era, opening hours, note, description) with no matching columns
-- in this schema; rather than add columns for a single new category,
-- built + note + description (and opening hours, where the source had it —
-- only the four cathedrals) are folded into the existing free-text notes
-- column, and era is dropped (the map colours by institution group, not
-- construction date, so it has no display surface here). Checked against
-- the existing seed for name clashes: none found.

on conflict (name) do nothing;
