insert into daysout.properties (name, location, country, institutions, latitude, longitude, notes)
values
  ('Canterbury Cathedral', 'Kent', 'England', array['Historic Church'], 51.2798, 1.0828, 'Founded 597; rebuilt from 1070s. Mother church of the Church of England; site of Becket''s martyrdom, 1170. England''s primary cathedral since 597 AD, seat of the Archbishop of Canterbury. A UNESCO World Heritage Site rebuilt from Romanesque to Perpendicular Gothic. Opening hours: Mon-Sat 10am-5pm (last entry 4pm); Sun grounds from 11:30am, cathedral from 12:30pm-5pm.'),
  ('Rochester Cathedral', 'Kent', 'England', array['Historic Church'], 51.3886, 0.5024, 'Founded 604; rebuilt from 1080s. England''s second-oldest cathedral, founded 604 AD. A Norman nave with a carved west doorway sits beside later Gothic quire and crypt, on a site used for worship since the 7th century. Opening hours: Mon-Fri 10am-5pm; Sat 10am-4pm; Sun 12pm-4pm.'),
  ('St Augustine''s, Brookland', 'Kent', 'England', array['Historic Church'], 50.9803, 0.7027, '13th century. Detached wooden belfry, leaning at a striking angle. On Romney Marsh, this church keeps its 13th-century octagonal timber bell-tower apart from the main building, shifted by soft marsh ground.'),
  ('St Dunstan''s, Cranbrook', 'Kent', 'England', array['Historic Church'], 51.0956, 0.5461, '14th-15th century. Known as the ''Cathedral of the Weald''. A grand Perpendicular Gothic parish church reflecting Cranbrook''s medieval wealth from the Kent wool and cloth trade.'),
  ('All Saints, Maidstone', 'Kent', 'England', array['Historic Church'], 51.2704, 0.5227, '1395-1420. The largest parish church in Kent, beside the River Medway. Rebuilt in the 14th century by Archbishop Courtenay, standing next to the Archbishop''s Palace on the Medway riverbank.'),
  ('St Mildred''s, Tenterden', 'Kent', 'England', array['Historic Church'], 51.0447, 0.6884, '15th century. Its tower has long guided travellers across the Weald. A spacious church at the heart of a former Cinque Port ''limb'' town, with a prominent 15th-century west tower.'),
  ('St Nicholas, Sevenoaks', 'Kent', 'England', array['Historic Church'], 51.2745, 0.1918, '15th century. Medieval parish church of the market town. A largely 15th-century building with an earlier tower, restored after wartime bomb damage, in the heart of Sevenoaks.'),
  ('St Peter & St Paul, Tonbridge', 'Kent', 'England', array['Historic Church'], 51.1930, 0.2745, '13th century, rebuilt 1877. Ragstone church beside Tonbridge Castle. A substantial parish church of Kentish ragstone, much rebuilt in the 19th century, standing near the Medway and the Norman castle.'),
  ('St Clement''s, Sandwich', 'Kent', 'England', array['Historic Church'], 51.2775, 1.3400, '11th-12th century. Grandest of Sandwich''s three medieval churches. A Norman central tower with striking arcaded decoration survives from this former Cinque Port''s most important church.'),
  ('St Leonard''s, Deal', 'Kent', 'England', array['Historic Church'], 51.2225, 1.4020, '12th century, much rebuilt. Historic parish church of Upper Deal. A part-Norman church with a sturdy tower, serving the older, inland part of Deal before the seafront developed.'),
  ('St Mary the Virgin, Dover', 'Kent', 'England', array['Historic Church'], 51.1279, 1.3117, '12th century, restored 1843. Ancient parish church near Dover''s Roman lighthouse. Standing close to the Roman Pharos and Saxon church within Dover Castle''s grounds, much restored in Victorian times.'),
  ('St Mary & St Eanswythe, Folkestone', 'Kent', 'England', array['Historic Church'], 51.0813, 1.1830, 'Founded 630; present church 13th century. Relics of a Saxon princess-saint found here in 1885. Built on the site of a 7th-century nunnery founded by St Eanswythe, whose rediscovered bones are still kept in the church.'),
  ('St Leonard''s, Hythe', 'Kent', 'England', array['Historic Church'], 51.0700, 1.0800, '13th century. Famous ossuary of ancient bones and skulls in its crypt. A grand church on a hillside above the Cinque Port town, its ambulatory crypt holds one of Britain''s largest bone collections.'),
  ('St Mary the Virgin, Ashford', 'Kent', 'England', array['Historic Church'], 51.1465, 0.8720, '15th century. Perpendicular Gothic church at the market town''s centre. Rebuilt in the 15th century with a prominent central tower, funded by the wealth of Ashford''s wool trade.'),
  ('St Mary of Charity, Faversham', 'Kent', 'England', array['Historic Church'], 51.3167, 0.8930, 'Medieval, spire rebuilt 1755. Unusual openwork crown spire, rare in England. One of Kent''s largest parish churches, rebuilt in the 18th century with a distinctive lantern spire visible across the marshes.'),
  ('All Saints, Whitstable', 'Kent', 'England', array['Historic Church'], 51.3600, 1.0250, '14th century, rebuilt 1876. Parish church of the old oyster-fishing town. A Victorian rebuilding of an older church, close to the harbour that made Whitstable famous for its oysters.'),
  ('St Martin''s, Herne', 'Kent', 'England', array['Historic Church'], 51.3617, 1.1280, '14th century. Medieval flint church of Herne village. A substantial 14th-century church with a tall tower, once the mother church of the neighbouring resort of Herne Bay.'),
  ('St John the Baptist, Margate', 'Kent', 'England', array['Historic Church'], 51.3860, 1.3830, '12th century, rebuilt 19th century. The old parish church predating Margate''s seaside growth. Kent''s largest parish church by area, with Norman origins beneath later medieval and Victorian rebuilding.'),
  ('St George''s, Ramsgate', 'Kent', 'England', array['Historic Church'], 51.3340, 1.4160, '1824-1827. Regency-era ''Cathedral of Thanet''. Built in 1827 with a landmark tower and spire, funded partly by tolls on shipping using Ramsgate''s harbour.'),
  ('St Mary''s, Minster-in-Thanet', 'Kent', 'England', array['Historic Church'], 51.3390, 1.3140, 'Founded 670; present fabric 11th-12th century. One of Britain''s oldest continuously used churches. Founded beside a 7th-century Saxon abbey, its Norman and earlier fabric make it among Kent''s most historic sites.'),
  ('St Mary''s, Wingham', 'Kent', 'England', array['Historic Church'], 51.2670, 1.1980, 'Founded 1286; rebuilt 14th century. Former collegiate church of a medieval community of priests. Founded as a college of priests in 1286, its unusually long chancel reflects that grander original purpose.'),
  ('St Mary''s, Chilham', 'Kent', 'England', array['Historic Church'], 51.2440, 0.9820, '15th century. Overlooks the timber-framed square of a picture-postcard village. A largely 15th-century church facing Chilham Castle across one of Kent''s best-preserved medieval village squares.'),
  ('St Gregory & St Martin, Wye', 'Kent', 'England', array['Historic Church'], 51.1830, 0.9370, 'Medieval, rebuilt 1706. Unusual double dedication in the Stour valley. Rebuilt after a tower collapse in 1686, this college-town church sits below the Wye Crown chalk hill figure.'),
  ('All Saints, Biddenden', 'Kent', 'England', array['Historic Church'], 51.1180, 0.6520, '14th century. Weald church linked to the legendary ''Biddenden Maids''. A 14th-century church at the centre of a timber-framed Wealden village, still tied to an ancient charity legend.'),
  ('St Michael''s, Smarden', 'Kent', 'England', array['Historic Church'], 51.1330, 0.6860, '14th century. Known locally as the ''Barn of Kent'' for its wide roof. A spacious medieval church with an unusually broad nave roof, reflecting Smarden''s cloth-trade prosperity.'),
  ('St Mary''s, Goudhurst', 'Kent', 'England', array['Historic Church'], 51.1120, 0.4530, '13th century, tower 1638. Hilltop church with sweeping Weald views. Sits at the highest point of the village, with fine monuments to the Culpeper family inside.'),
  ('St George''s, Benenden', 'Kent', 'England', array['Historic Church'], 51.0700, 0.6580, 'Medieval, rebuilt after 1830s fire. Weald village church rebuilt after an 1830s fire. A largely 19th-century rebuild on a medieval site, in a quiet Wealden village near Benenden School.'),
  ('All Saints, Lydd', 'Kent', 'England', array['Historic Church'], 50.9520, 0.9110, '13th-15th century. The true ''Cathedral of the Marsh'', tallest tower on Romney Marsh. One of the longest parish churches in England, its soaring tower dominates the flat expanse of Romney Marsh.'),
  ('St Nicholas, New Romney', 'Kent', 'England', array['Historic Church'], 50.9970, 0.9420, '12th century. Norman church left stranded by a shifting shoreline. Once a thriving Cinque Port harbour church, a 13th-century storm silted up the sea and left the town inland.'),
  ('St Thomas Becket, Fairfield', 'Kent', 'England', array['Historic Church'], 51.0080, 0.8720, '13th century (rebuilt 1912). An isolated timber-framed chapel alone in a marsh field. Reached by a footpath across sheep pasture, this weatherboarded church is one of Romney Marsh''s most photographed sights.'),
  ('St Mary''s Abbey, West Malling', 'Kent', 'England', array['Historic Church'], 51.2900, 0.4080, 'Founded c.1090. Still an active Benedictine community. Founded around 1090, the abbey church continues as home to an Anglican Benedictine order of nuns today.'),
  ('St Peter & St Paul, Aylesford', 'Kent', 'England', array['Historic Church'], 51.3050, 0.4880, '13th-14th century. Riverside church in a village of ancient bridges. Overlooks the Medway''s historic multi-arched bridge, near the Carmelite friary known as The Friars.'),
  ('St Nicholas, Leeds', 'Kent', 'England', array['Historic Church'], 51.2500, 0.6300, '12th century. Village church near the moated Leeds Castle. A part-Norman church in the village that lends its name to the famous moated castle nearby.'),
  ('St Mary''s, Chartham', 'Kent', 'England', array['Historic Church'], 51.2530, 1.0080, '13th century. Well-preserved medieval brasses on the Stour. A 13th-century church noted for its collection of monumental brasses, beside the River Stour near Canterbury.'),
  ('Holy Cross, Bearsted', 'Kent', 'England', array['Historic Church'], 51.2670, 0.5850, '13th-14th century. Faces one of Kent''s classic village greens. A medieval flint church overlooking the cricket green at Bearsted, a village little changed in outline for centuries.'),
  ('St Peter & St Paul, Headcorn', 'Kent', 'England', array['Historic Church'], 51.1630, 0.6440, '14th century. One of Kent''s widest timber church roofs. A 14th-century Wealden church with an exceptionally broad nave, funded by the medieval cloth industry.'),
  ('St Bartholomew''s, Otford', 'Kent', 'England', array['Historic Church'], 51.3170, 0.1980, 'Medieval, rebuilt 1853. Near the ruins of a former archbishops'' palace. A Norman-founded church beside the Darent, close to the remains of Otford Palace, once used by Tudor archbishops.'),
  ('St Mary''s, Westerham', 'Kent', 'England', array['Historic Church'], 51.2660, 0.0740, '13th century, restored 19th century. Winston Churchill''s local parish church. A medieval church in the market town where Churchill lived at nearby Chartwell, with memorials to him inside.'),
  ('St Peter & St Paul, Edenbridge', 'Kent', 'England', array['Historic Church'], 51.1980, 0.0670, '13th century. Timber-framed high street church near the Surrey border. A part-13th-century church at the western edge of Kent, in a town that grew around an ancient Eden Bridge crossing.'),
  ('St Mary''s, Lenham', 'Kent', 'England', array['Historic Church'], 51.2160, 0.6980, '13th-14th century. Anchors a well-preserved square below the North Downs. A substantial medieval church facing Lenham''s timber-framed market square at the foot of the chalk downs.'),
  ('St Peter & St Paul, Charing', 'Kent', 'England', array['Historic Church'], 51.2010, 0.7910, 'Medieval, rebuilt after 1590 fire. Former resting place for pilgrims to Canterbury. Sits by the ruins of a palace once used by archbishops, on the old pilgrim road to Canterbury.'),
  ('St Nicholas, Chislehurst', 'Kent', 'England', array['Historic Church'], 51.4160, 0.0680, 'Medieval, rebuilt 1980s after fire. Common-side church at Kent''s historic north-west edge. A rebuilt medieval church facing Chislehurst Common, in what was historically part of Kent before boundary changes.'),
  ('St Peter''s, Ightham', 'Kent', 'England', array['Historic Church'], 51.2890, 0.2350, '13th century. Village church near the moated Ightham Mote. A part-13th-century church in a village famed for its beautifully preserved medieval moated manor house nearby.'),
  ('St Mary Magdalene, Cobham', 'Kent', 'England', array['Historic Church'], 51.3900, 0.4020, '13th-14th century. Renowned collection of medieval memorial brasses. Holds one of England''s finest sets of monumental brasses, alongside almshouses founded by the Cobham family.'),
  ('St Michael''s, Lewes', 'East Sussex', 'England', array['Historic Church'], 50.8724, 0.0116, '12th century. One of only three round-towered churches in Sussex. A flint church on the historic High Street, its unusual round Norman tower a landmark in the county town.'),
  ('St Mary the Virgin, Battle', 'East Sussex', 'England', array['Historic Church'], 50.9155, 0.4835, '12th-13th century. Overlooks the 1066 battlefield and Battle Abbey. A largely 13th-century church with medieval wall paintings, beside the abbey founded on the site of William''s victory.'),
  ('St Thomas the Apostle, Winchelsea', 'East Sussex', 'England', array['Historic Church'], 50.9269, 0.7079, 'Begun 1288. The chancel of a once-cathedral-scale church. Only part of the intended vast church was completed before French raids in the 14th century; fine tomb effigies survive.'),
  ('St Mary''s, Rye', 'East Sussex', 'England', array['Historic Church'], 50.9500, 0.7333, '12th century, much added since. Its turret clock, from 1561, is one of England''s oldest working. A large hilltop church mixing Norman and later work, with wide views over Romney Marsh from the tower.'),
  ('St Mary''s, Eastbourne (Old Town)', 'East Sussex', 'England', array['Historic Church'], 50.7700, 0.2750, '12th century. The original parish church, predating the Victorian resort. A Norman-founded church in Eastbourne''s Old Town, well inland of the seafront that later made the town famous.'),
  ('St Clement''s, Hastings', 'East Sussex', 'England', array['Historic Church'], 50.8560, 0.5730, 'Medieval, rebuilt 1630s. Georgian rebuild in the winding Old Town. Rebuilt after storm damage in the 1630s, this is the parish church of Hastings'' historic Old Town lanes.'),
  ('St Peter''s, Bexhill (Old Town)', 'East Sussex', 'England', array['Historic Church'], 50.8400, 0.4700, 'Saxon origins; Norman additions c.1080s. Ancient parish church of pre-Victorian Bexhill. A Saxon-founded church with Norman additions, in the original village that predates the seaside town by centuries.'),
  ('St Nicolas, Pevensey', 'East Sussex', 'England', array['Historic Church'], 50.8190, 0.3330, '13th century. Within sight of the Roman and Norman fortress. A 13th-century church close to Pevensey Castle, near where William the Conqueror''s fleet landed in 1066.'),
  ('All Saints, Herstmonceux', 'East Sussex', 'England', array['Historic Church'], 50.8850, 0.3320, '13th-14th century. Village church near the moated Tudor castle. A part-medieval church close to Herstmonceux Castle, once home to the Royal Greenwich Observatory.'),
  ('St Andrew''s, Alfriston', 'East Sussex', 'England', array['Historic Church'], 50.8050, 0.1670, '14th century. Called the ''Cathedral of the Downs''. A large 14th-century cruciform church on the village green, beside the Clergy House, the first building acquired by the National Trust.'),
  ('St Michael''s, Berwick', 'East Sussex', 'England', array['Historic Church'], 50.8330, 0.1780, 'Medieval; murals added 1940s. Interior murals by the Bloomsbury Group. Decorated in the 1940s by Vanessa Bell and Duncan Grant, its painted walls are unique among Sussex churches.'),
  ('St Mary & St Peter, Wilmington', 'East Sussex', 'England', array['Historic Church'], 50.8080, 0.1930, '12th century. Beneath the chalk-cut Long Man of Wilmington. A small Norman-founded church with an ancient yew tree, at the foot of the hillside figure it takes its village name from.'),
  ('St Leonard''s, Seaford', 'East Sussex', 'England', array['Historic Church'], 50.7710, 0.1050, '12th century, much rebuilt. Parish church of the old Cinque Port town. A part-Norman church much restored after medieval French raids on this former Channel port.'),
  ('St Mary''s, Ringmer', 'East Sussex', 'England', array['Historic Church'], 50.8880, 0.0870, '13th century. Weald-edge village church near Lewes. A medieval flint church with later brick additions, serving a village long associated with Gideon Mantell''s fossil discoveries nearby.'),
  ('St Dunstan''s, Mayfield', 'East Sussex', 'England', array['Historic Church'], 51.0140, 0.2760, 'Rebuilt after 1389 fire. Linked to the legend of the saint and the Devil''s tongs. Rebuilt after a 14th-century fire, the church stands beside the medieval palace where St Dunstan is said to have worked as a smith.'),
  ('St Peter & St Paul, Wadhurst', 'East Sussex', 'England', array['Historic Church'], 51.0530, 0.3400, '13th century. Cast-iron memorial slabs from the Wealden iron industry. Its floor holds one of the country''s largest collections of iron grave slabs, made in local Wealden furnaces.'),
  ('St Mary''s, Ticehurst', 'East Sussex', 'England', array['Historic Church'], 51.0480, 0.4270, '14th century. High Weald church with a shingled spire. A 14th-century church with later Georgian brick additions, in a High Weald village near the Kent border.'),
  ('St Bartholomew''s, Burwash', 'East Sussex', 'England', array['Historic Church'], 50.9950, 0.4160, '13th century. Rudyard Kipling''s local parish church. Kipling lived nearby at Bateman''s; the church holds an ancient iron grave slab, among the oldest cast in England.'),
  ('St Mary''s, Salehurst', 'East Sussex', 'England', array['Historic Church'], 50.9840, 0.4460, '13th century. Serves Robertsbridge, beside a former Cistercian abbey. A substantial 13th-century church near the ruins of Robertsbridge Abbey, in the Rother valley.'),
  ('St Giles'', Bodiam', 'East Sussex', 'England', array['Historic Church'], 50.9910, 0.5590, '14th century. Neighbours one of England''s most photographed castles. A modest medieval church a short walk from the moated Bodiam Castle, built during the Hundred Years'' War.'),
  ('St Mary''s, Northiam', 'East Sussex', 'England', array['Historic Church'], 50.9880, 0.6280, 'Part-Saxon; mostly 14th-15th century. Queen Elizabeth I is said to have rested under its yew. A part-Saxon church with a famous ancient yew tree on the green, where the queen reputedly changed her shoes in 1573.'),
  ('Holy Cross, Uckfield', 'East Sussex', 'England', array['Historic Church'], 50.9700, 0.0900, 'Rebuilt 1839. Victorian rebuild at the edge of the High Weald. Largely reconstructed in the 19th century, serving the market town where the Weald meets the Sussex Ouse valley.'),
  ('St Denys, Rotherfield', 'East Sussex', 'England', array['Historic Church'], 51.0470, 0.2270, 'Saxon origins; 13th-century fabric. Faint medieval wall paintings survive inside. A Saxon-founded hilltop church with traces of 13th-century murals, overlooking the source of the River Rother.'),
  ('All Saints, Heathfield', 'East Sussex', 'England', array['Historic Church'], 50.9670, 0.2620, '13th century, much rebuilt. High Weald parish church above the old cuckoo fair town. Serves a High Weald market town traditionally said to welcome the first cuckoo of spring at its April fair.'),
  ('St Swithun''s, East Grinstead', 'East Sussex', 'England', array['Historic Church'], 51.1280, -0.0090, 'Rebuilt 1789. Georgian rebuild after a tower collapse. Rebuilt in the 1780s after its medieval predecessor''s tower fell, on Sussex''s border with Surrey and Kent.'),
  ('Chichester Cathedral', 'West Sussex', 'England', array['Historic Church'], 50.8365, -0.7792, '1076-1108. Its spire is visible from the sea; a rare English cathedral spire. Consecrated 1108, with a free-standing medieval bell tower and a modern tapestry behind the high altar. Opening hours: Mon-Sat 9am-5pm; Sun 12:30pm-2:30pm.'),
  ('Arundel Cathedral', 'West Sussex', 'England', array['Historic Church'], 50.8551, -0.5556, '1868-1873. French Gothic-revival, built 1868-1873. A Roman Catholic cathedral commissioned by the Duke of Norfolk, modelled on 13th-century French cathedrals. Opening hours: Mon-Sat 9am-4pm; Sun 12:30pm-4pm.'),
  ('Boxgrove Priory', 'West Sussex', 'England', array['Historic Church'], 50.8577, -0.6797, 'c.1200 (choir). Surviving choir of a Benedictine priory church. Only the 12th-century quire and crossing remain in use as the parish church, amid the wider priory ruins.'),
  ('St Andrew''s, Steyning', 'West Sussex', 'England', array['Historic Church'], 50.8887, -0.3226, '12th century. Among the finest Norman naves in Sussex. Built on the site of a Saxon minster linked to St Cuthman, its round-arched nave is renowned for its carved stonework.'),
  ('Holy Trinity, Bosham', 'West Sussex', 'England', array['Historic Church'], 50.8267, -0.8617, 'Saxon; chancel arch c.1050. Appears in the Bayeux Tapestry; a Saxon chancel arch survives. King Harold is shown praying here before his 1064 voyage; genuine Anglo-Saxon stonework remains in the chancel arch.'),
  ('St Mary''s, Horsham', 'West Sussex', 'England', array['Historic Church'], 51.0625, -0.3272, '13th century. Sussex ''Horsham slab'' stone roof tiles overhead. A 13th-century church roofed in the heavy local sandstone slabs typical of the Horsham area.'),
  ('St Mary''s, Petworth', 'West Sussex', 'England', array['Historic Church'], 50.9970, -0.6106, 'Medieval, rebuilt 1827. Beside the grand parkland of Petworth House. Largely rebuilt in the 19th century, standing at the edge of the National Trust estate and its Capability Brown park.'),
  ('St Mary Magdalene & St Denys, Midhurst', 'West Sussex', 'England', array['Historic Church'], 50.9830, -0.7370, 'Medieval, rebuilt 1880s. Unusual double dedication in a Rother-valley market town. A largely rebuilt Victorian church on a medieval site, near the ruins of Cowdray House.'),
  ('St Mary''s, Pulborough', 'West Sussex', 'England', array['Historic Church'], 50.9560, -0.5170, '12th century. Hilltop church above the Arun water-meadows. A part-Norman church with wide views over the River Arun''s flood plain from its raised churchyard.'),
  ('St Michael''s, Amberley', 'West Sussex', 'England', array['Historic Church'], 50.9080, -0.5460, '12th century. Thatched-cottage village beneath the South Downs. A Norman church with later medieval work, in a village of thatched cottages between the Downs and the Arun wetlands.'),
  ('St Nicholas, Bramber', 'West Sussex', 'England', array['Historic Church'], 50.8890, -0.3000, '12th century. Below the motte of Bramber Castle. What remains is the nave of a larger Norman church built alongside the castle founded soon after 1066.'),
  ('St Mary de Haura, Shoreham-by-Sea', 'West Sussex', 'England', array['Historic Church'], 50.8340, -0.2740, 'c.1103. Name means ''St Mary of the Harbour''. A grand Transitional Norman church, once much larger, reflecting Shoreham''s importance as a medieval port.'),
  ('St Mary''s, Broadwater, Worthing', 'West Sussex', 'England', array['Historic Church'], 50.8210, -0.3760, '12th century. Worthing''s ancient mother church, inland of the seafront. A Norman cruciform church that served as the parish centre long before Worthing grew into a seaside town.'),
  ('St John the Baptist, Findon', 'West Sussex', 'England', array['Historic Church'], 50.8890, -0.4230, '13th century. Downland village church near the sheep fair site. A part-medieval church in a village long known for its historic Findon Sheep Fair on the surrounding Downs.'),
  ('Holy Trinity, Cuckfield', 'West Sussex', 'England', array['Historic Church'], 51.0030, -0.1440, '13th century. Notable medieval roof and wall paintings. A 13th-century church with an elaborately painted wagon roof, at the centre of a well-preserved High Weald village.'),
  ('St Mary Magdalene, Bolney', 'West Sussex', 'England', array['Historic Church'], 50.9840, -0.2140, '13th century. Weald village church of timber and sandstone. A part-13th-century church with a shingled spire, in a scattered Weald parish between Cuckfield and Henfield.'),
  ('St Peter''s, Henfield', 'West Sussex', 'England', array['Historic Church'], 50.9270, -0.2760, '13th century. Overlooks the upper Adur valley. A largely 13th-century church with a later tower, above the water-meadows of the young River Adur.'),
  ('St Mary''s, Sullington', 'West Sussex', 'England', array['Historic Church'], 50.9280, -0.4680, '11th century. Saxon origins, among the oldest churches in Sussex. Retains herringbone Saxon masonry and a Norman font, in a small downland parish near Storrington.'),
  ('St Peter''s, Selsey', 'West Sussex', 'England', array['Historic Church'], 50.7350, -0.7910, 'Medieval; original see lost by 1075. Selsey was the original seat of the South Saxon bishopric. The first Sussex cathedral stood near here before the sea claimed the site and the see moved to Chichester in 1075.'),
  ('St Mary Magdalene, South Bersted', 'West Sussex', 'England', array['Historic Church'], 50.7860, -0.6870, 'Medieval, rebuilt 19th century. The historic parish church serving Bognor Regis. A part-medieval church in the older settlement of South Bersted, which the Georgian resort of Bognor grew up beside.'),
  ('St Mary''s, Climping', 'West Sussex', 'England', array['Historic Church'], 50.8050, -0.5670, '13th century. Unspoiled Norman and Early English work near the coast. Little altered since the 13th century, with a fine carved south doorway, close to the Arun''s mouth at Littlehampton.'),
  ('St Nicholas, Brighton', 'West Sussex', 'England', array['Historic Church'], 50.8250, -0.1500, 'Medieval, rebuilt 1853. The ''Mother Church of Brighton'', on a hill above the town. Medieval in origin, it holds a rare 12th-century black Tournai marble font, predating Brighton''s Regency growth by centuries.'),
  ('St John the Baptist, Sedlescombe', 'East Sussex', 'England', array['Historic Church'], 50.9394, 0.5090, '13th century. A pretty Wealden village on the old road to Hastings. Rebuilt in the early English style in the 13th century on an earlier Norman site, with a south aisle added in 1838.'),
  ('St George, Crowhurst', 'East Sussex', 'England', array['Historic Church'], 50.8779, 0.4644, '12th century; tower 15th century. Recorded here since 772 AD, with a link to King Harold. A 12th-century nave stands beneath a 15th-century tower bearing the Pelham buckle, beside one of Sussex''s largest ancient yew trees.'),
  ('St Laurence, Catsfield', 'East Sussex', 'England', array['Historic Church'], 50.8768, 0.4562, 'Nave c.1100; tower and chancel early 13th century. Recorded in the Domesday Book of 1086. An early Norman nave with a late 12th-century tower, its 13th-century chancel and 19th-century north aisle added around the original core.'),
  ('St Mary the Virgin, Ninfield', 'East Sussex', 'England', array['Historic Church'], 50.8564, 0.4310, '11th-century nave; 13th-century doorway. Stands apart from the village; also recorded in Domesday Book. A modest Norman-founded church with an early 13th-century west doorway, its plain interior shaped mostly by later post-Reformation work.'),
  ('All Saints, Mountfield', 'East Sussex', 'England', array['Historic Church'], 50.9814, 0.5099, 'Nave c.1107-1124; tower c.1180-1200. A little-altered Norman church in the woods west of Battle. Holds the second-largest Norman font in Sussex, with chancel wall paintings ranging from the 12th to the 16th century.'),
  ('St Mary Magdalene, Whatlington', 'East Sussex', 'England', array['Historic Church'], 50.9506, 0.5324, '12th century or earlier; chancel extended 13th century. A remote church in wooded country north-east of Battle. Likely Norman in origin, though only 13th-century and later detail survives visibly today, following restoration in 1862 and a fire in 2012.')
